with total as(select count(*)::int as total_count,max(a.sequence)::text as latest_sequence from research_question_answers a where a.project_id=$1::uuid and a.research_question_id=$2::uuid and a.finalized_at is not null), answer_page as(
  select a.id,a.sequence::text as sequence,a.finalized_at,left(a.answer_text,300) as text_preview
  from research_question_answers a where a.project_id=$3::uuid and a.research_question_id=$4::uuid and a.finalized_at is not null and a.sequence<=(select coalesce(max(x.sequence),0) from research_question_answers x where x.project_id=$5::uuid and x.research_question_id=$6::uuid and x.finalized_at is not null) 
  order by a.sequence desc,a.id desc limit $7
) select t.total_count,t.latest_sequence,((select coalesce(max(x.sequence),0) from research_question_answers x where x.project_id=$8::uuid and x.research_question_id=$9::uuid and x.finalized_at is not null))::text as high_water_sequence,p.id,p.sequence,p.finalized_at,p.text_preview,
  coalesce(f.claim_context_count,0)::int as claim_context_count,coalesce(f.synthesis_context_count,0)::int as synthesis_context_count,coalesce(f.drifted_context_count,0)::int as drifted_context_count
from total t left join answer_page p on true left join lateral(
  select count(*) filter(where d.context_type='claim')::int as claim_context_count,count(*) filter(where d.context_type='synthesis')::int as synthesis_context_count,count(*) filter(where d.superseded or d.withdrawn or d.unlinked)::int as drifted_context_count
  from (
    select 'claim'::text as context_type,(cur.id is distinct from c.claim_revision_id) as superseded,(cur.state='withdrawn') as withdrawn,((select e.action from research_question_claim_events e where e.project_id=c.project_id and e.research_question_id=c.research_question_id and e.claim_id=c.claim_id order by e.sequence desc,e.id desc limit 1) is distinct from 'linked') as unlinked
    from research_question_answer_claim_contexts c left join lateral(select r.id,r.state from claim_revisions r where r.project_id=c.project_id and r.claim_id=c.claim_id and r.finalized_at is not null order by r.sequence desc limit 1) cur on true where p.id is not null and c.project_id=$10::uuid and c.research_question_id=$11::uuid and c.answer_id=p.id
    union all
    select 'synthesis',(cur.id is distinct from c.synthesis_revision_id),(cur.state='withdrawn'),((select e.action from research_question_synthesis_statement_events e where e.project_id=c.project_id and e.research_question_id=c.research_question_id and e.synthesis_statement_id=c.synthesis_statement_id order by e.sequence desc,e.id desc limit 1) is distinct from 'linked')
    from research_question_answer_synthesis_contexts c left join lateral(select r.id,r.state from synthesis_revisions r where r.project_id=c.project_id and r.synthesis_statement_id=c.synthesis_statement_id and r.finalized_at is not null order by r.sequence desc limit 1) cur on true where p.id is not null and c.project_id=$12::uuid and c.research_question_id=$13::uuid and c.answer_id=p.id
  ) d
) f on true

